$seedIds=@{lab_report_job='30001';lab_report_instance='30001';lab_report_summary='30001,30002';lab_report_section='30001,30002,30003,30004,30005,30006';lab_report_template='30001';lab_period_close='30001';lab_perf_score='30001,30002,30003';lab_collaboration_record='30001';lab_ipr='30001,30002';lab_one2one='30001';lab_member_skill='30001,30002,30003,30004,30005';lab_skill='30001,30002,30003';lab_reminder='30001,30002';lab_task_block_event='30001,30002';lab_task_quality_gate='30001,30002';lab_task_evidence='30001,30002';lab_task='30001,30002,30003,30004,30005';lab_goal='30001,30002,30003,30004';lab_asset='30001,30002,30003';lab_member='30001,30002,30003,30004,30005,30006'}; Require (-not ($sql -match '(?is)DELETE\s+FROM[^;]+BETWEEN')) 'Range cleanup is unsafe.'; foreach($table in $seedIds.Keys){Require ($sql.Contains("DELETE FROM ``$table`` WHERE ``id`` IN ($($seedIds[$table]));")) "Exact cleanup IDs missing: $table"}
$users=Get-InsertRows 'sys_user'; Require ($users.Count -eq 6) 'Exactly six demo users required.'; $hashes=@(); $base='$2a$10$7JB720yubVSZvUI0rEqK/.VqGOZTH.ulu33dHOiBE8ByOhJIrdAu2'; foreach($user in $users){Require ((Unquote $user[10]) -eq '1') 'Demo users must be disabled.'; $hash=Unquote $user[9]; Require ($hash -match '^\$2[aby]\$[0-9]{2}\$[./A-Za-z0-9]{53}$') 'Demo password must be BCrypt shaped.'; Require ($hash -ne $base) 'Baseline admin hash is forbidden.'; $hashes += $hash}; Require (($hashes | Select-Object -Unique).Count -eq 6) 'Demo BCrypt hashes must be distinct.'
