$quote=$false; $depth=0; for($i=0;$i -lt $sql.Length;$i++){ $c=$sql[$i]; if($c -eq "'" -and ($i -eq 0 -or $sql[$i-1] -ne '\')){$quote=-not $quote}; if(-not $quote -and $c -eq '('){$depth++}; if(-not $quote -and $c -eq ')'){$depth--; Require ($depth -ge 0) 'Unbalanced SQL closing parenthesis.'} }; Require (-not $quote -and $depth -eq 0) 'Unbalanced SQL string literal or parentheses.'
